function Counter() {
  const [count, setCount] = useState(0);

  function addThree() {
    setCount((previous) => previous + 1);
    setCount((previous) => previous + 1);
    setCount((previous) => previous + 1);
  }

  return <button type="button" onClick={addThree}>현재 값: {count}</button>;
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Counter />);

